globalJavaScript:
// ==========================================================================
// 1. Paste your OpenAI API key between the quotes below (replace the
//    placeholder). Get one at https://platform.openai.com/api-keys
// 2. Optionally change the model.
// NOTE: the key lives only on your device inside Gboard's settings. Never
//       share an exported copy of this file with the key filled in.
// ==========================================================================
var OPENAI_API_KEY = "PUT_YOUR_OPENAI_API_KEY_HERE";
var OPENAI_MODEL   = "gpt-5.5";

function ai(instruction, text){
  if (!OPENAI_API_KEY || OPENAI_API_KEY === "PUT_YOUR_OPENAI_API_KEY_HERE"){
    return "\u26A0\uFE0F Set OPENAI_API_KEY in Global JavaScript first.";
  }
  var src = String(text || "").trim();
  var prompt = src ? (instruction + ":\n\n" + src) : instruction;
  var raw = httpRequest({
    method: "POST",
    url: "https://api.openai.com/v1/responses",
    headers: {
      "Content-Type": "application/json",
      "Authorization": "Bearer " + OPENAI_API_KEY
    },
    body: JSON.stringify({ model: OPENAI_MODEL, input: prompt })
  });
  var res;
  try { res = JSON.parse(raw); } catch (e) { return "\u26A0\uFE0F Bad response from API."; }
  if (res.error){ return "\u26A0\uFE0F " + res.error.message; }
  if (res.output_text){ return res.output_text; }
  var first = res.output && res.output[0];
  var c = first && first.content && first.content[0];
  return (c && c.text) ? c.text : "";
}
